def run(_context):
    import json
    # Delete the duplicate "Face Top" operation
    cam = mb.get_cam()
    setup = cam.setups.itemByName("Setup1")
    # Find the operation first
    op_to_delete = None
    for i in range(setup.operations.count):
        op = setup.operations.item(i)
        try:
            name = op.name
            if name == "Face Top":
                op_to_delete = op
                break
        except:
            pass
    if op_to_delete:
        op_to_delete.deleteMe()
        print("Deleted: Face Top")
    else:
        print("Face Top not found")
    # Verify
    probe = mb.probe()
    print("\n=== PROBE AFTER DELETE ===")
    for s in probe["setups"]:
        for op in s["operations"]:
            print(f"  {op['name']}: has_toolpath={op['has_toolpath']}, is_valid={op['is_valid']}")

